def page(slug,title,desc,eyebrow,h1,intro,quick,body,faq=None):
    canonical=f'{HOST}/{slug}'
    q=''.join(f'<div><b>{a}</b><span>{b}</span></div>' for a,b in quick)
    faq_json=''
    if faq:
        import json
        data={"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":qq,"acceptedAnswer":{"@type":"Answer","text":aa}} for qq,aa in faq]}
        faq_json=f'<script type="application/ld+json">{json.dumps(data,ensure_ascii=False)}</script>'
    article=f'''{{"@context":"https://schema.org","@type":"Article","headline":"{title}","description":"{desc}","dateModified":"{TODAY}","inLanguage":"vi-VN","mainEntityOfPage":"{canonical}","publisher":{{"@type":"Organization","name":"TNS Worldwide"}},"about":{{"@type":"CollegeOrUniversity","name":"Xi\'an Jiaotong-Liverpool University","alternateName":"XJTLU"}}}}'''
    return f'''<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>{title}</title><meta name="description" content="{desc}"><meta name="robots" content="index,follow,max-snippet:-1,max-image-preview:large"><link rel="canonical" href="{canonical}"><meta property="og:type" content="article"><meta property="og:locale" content="vi_VN"><meta property="og:site_name" content="XJTLU Việt Nam"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{canonical}"><script type="application/ld+json">{article}</script>{faq_json}<style>{CSS}</style></head><body><nav class="nav"><div class="wrap"><a class="brand" href="/">XJTLU Việt Nam</a><button class="menu-btn" type="button" onclick="toggleMenu(true)">Menu ☰</button></div></nav>{MENU}<header class="hero"><div class="wrap"><div class="eyebrow">{eyebrow}</div><h1>{h1}</h1><p>{intro}</p><div class="updated">Cập nhật: 09/09/2026</div></div></header><div class="wrap quick">{q}</div><main class="wrap">{body}</main>{CONTACT}{SCRIPT}</body></html>'''

CITY_BODY='''
<div class="answer"><strong>Trả lời nhanh:</strong> Tô Châu không chỉ là “thành phố gần Thượng Hải”. Với sinh viên Việt Nam, đây là một trung tâm sản xuất – thương mại có quan hệ trực tiếp và rất lớn với Việt Nam, đồng thời nằm trong vùng kinh tế Trường Giang cùng Thượng Hải.</div>
<section class="section"><h2>Việt Nam là đối tác thương mại lớn của Tô Châu</h2><p class="lead">Năm 2025, kim ngạch xuất nhập khẩu giữa Tô Châu và Việt Nam đạt khoảng <strong>204,75 tỷ RMB</strong>, tăng 29,1%. Đến 2026, Việt Nam là đối tác thương mại lớn thứ hai của Tô Châu và là đối tác lớn nhất của thành phố trong ASEAN.</p><div class="grid3"><div class="stat"><b>204,75 tỷ RMB</b><span>thương mại Tô Châu – Việt Nam năm 2025</span></div><div class="stat"><b>+29,1%</b><span>tăng trưởng so với năm trước</span></div><div class="stat"><b>+50,6%</b><span>tăng trưởng 4 tháng đầu 2026</span></div></div><div class="notice" style="margin-top:16px">Điểm đáng chú ý là mối liên kết này đến từ các ngành rất gần với chương trình của XJTLU: điện tử, thiết bị máy móc, dệt may, sản xuất, logistics và chuỗi cung ứng.</div></section>
<section class="section"><h2>Từ Tô Châu đến Việt Nam: đường sắt, đường bộ, hàng không và đường biển</h2><div class="grid"><article class="card"><h3>Hành lang logistics mới</h3><p>Tháng 6/2026, Tô Châu đồng thời khai trương tuyến tàu hàng quốc tế, xe tải quốc tế và chuyến bay hàng hóa charter đi Việt Nam. Thành phố đã có sẵn các tuyến đường biển Đông Nam Á.</p></article><article class="card"><h3>Ý nghĩa với sinh viên</h3><p>Học supply chain, business, economics, engineering, data hay công nghệ tại đây đồng nghĩa bạn đang sống trong một khu vực có luồng thương mại thật với Việt Nam, thay vì chỉ học khái niệm trong lớp.</p></article></div></section>
<section class="section"><h2>Thượng Hải mở rộng “bán kính” của XJTLU</h2><p class="lead">Tô Châu và Thượng Hải nằm rất gần nhau. Từ Shanghai Hongqiao đến Tô Châu có nhiều chuyến tàu cao tốc khoảng 25–30 phút; từ sân bay Hongqiao đến XJTLU SIP khoảng 70 km, còn từ Pudong khoảng 120 km.</p><div class="grid"><article class="card"><h3>Hà Nội / TP.HCM → Thượng Hải</h3><p>Vietnam Airlines hiện bán hành trình Hà Nội – Thượng Hải và TP.HCM – Thượng Hải. Vì vậy với sinh viên Việt Nam, Thượng Hải là cửa ngõ hàng không thực tế để đến XJTLU.</p></article><article class="card"><h3>Thượng Hải – TP.HCM</h3><p>Hai thành phố tiếp tục mở rộng hợp tác về đầu tư, thương mại, tài chính, chuyển đổi số, phát triển xanh, giáo dục và giao lưu thanh niên. Với sinh viên Việt Nam, “Tô Châu + Thượng Hải” tạo thành một vùng học tập và trải nghiệm rộng hơn một thành phố.</p></article></div></section>
<section class="section"><h2>Ngành nào ở XJTLU hưởng lợi nhiều nhất từ bối cảnh này?</h2><div class="grid"><article class="card"><h3>Supply Chain & Business</h3><p>Quan sát trực tiếp chuỗi cung ứng Trung Quốc – Việt Nam, logistics, thương mại và doanh nghiệp đa quốc gia.</p></article><article class="card"><h3>AI, Data & Computer Science</h3><p>SIP là khu vực tập trung công nghệ và doanh nghiệp quốc tế; dữ liệu và tự động hóa gắn chặt với sản xuất – logistics.</p></article><article class="card"><h3>Engineering & Manufacturing</h3><p>Tô Châu mạnh về điện tử, thiết bị và sản xuất; đây cũng là nhóm ngành có liên kết thương mại lớn với Việt Nam.</p></article><article class="card"><h3>Economics & Finance</h3><p>Thương mại xuyên biên giới và vị trí gần Thượng Hải giúp sinh viên thấy rõ hơn cách dòng vốn, sản xuất và thị trường vận hành trong khu vực.</p></article></div><div class="notice" style="margin-top:16px">Bối cảnh thành phố không đảm bảo việc làm hay thực tập. Giá trị nằm ở việc học bằng tiếng Anh trong khi sống giữa một hệ sinh thái kinh tế có liên hệ trực tiếp với Việt Nam.</div></section>
<section class="section"><h2>Cuộc sống: một thành phố Trung Quốc, nhưng không bị tách khỏi châu Á</h2><p class="lead">Tô Châu có khu phố cổ, kênh đào và vườn truyền thống, đồng thời SIP lại là khu đô thị hiện đại với trung tâm thương mại, tàu điện ngầm, hồ Jinji và nhiều doanh nghiệp quốc tế. Khi cần nhiều lựa chọn hơn về sự kiện, mua sắm, hàng không hay trải nghiệm quốc tế, Thượng Hải ở ngay bên cạnh.</p></section>
<section class="section"><h2>Xem tiếp</h2><div class="related"><a href="/xjtlu-nganh-hoc-nghe-nghiep.html">Ngành học & nghề nghiệp<span>Xem ngành phù hợp với mục tiêu Việt Nam – Trung Quốc</span></a><a href="/xjtlu-chi-phi-sinh-hoat-2027.html">Chi phí sinh hoạt<span>Lập ngân sách thực tế tại Tô Châu</span></a><a href="/xjtlu-ky-tuc-xa-sip-taicang.html">Ký túc xá<span>So sánh SIP và Taicang</span></a></div></section>'''

CITY_FAQ=[('Tô Châu có gần Thượng Hải không?','Có. Tàu cao tốc từ Shanghai Hongqiao đến Tô Châu thường mất khoảng 25–30 phút; XJTLU SIP cách sân bay Hongqiao khoảng 70 km.'),('Tô Châu có quan hệ kinh tế đáng kể với Việt Nam không?','Có. Năm 2025 thương mại Tô Châu – Việt Nam đạt khoảng 204,75 tỷ RMB; Việt Nam hiện là đối tác thương mại lớn thứ hai của Tô Châu và lớn nhất trong ASEAN.'),('Học ở Tô Châu có nghĩa phải làm việc tại Trung Quốc sau tốt nghiệp không?','Không. Điểm mạnh là có thêm trải nghiệm Trung Quốc và hiểu thị trường trong khi học bằng tiếng Anh; kế hoạch nghề nghiệp có thể ở Việt Nam, Trung Quốc hoặc thị trường khác.')]

COST_BODY='''
<div class="answer"><strong>Trả lời nhanh:</strong> XJTLU đưa ra ba kịch bản tham khảo khoảng <strong>3.700 / 6.450 / 9.600 RMB mỗi tháng</strong>. Chênh lệch lớn nhất thường đến từ loại chỗ ở, ăn uống và mức chi tiêu cá nhân.</div>
<section class="section"><h2>3 mức ngân sách hàng tháng</h2><div class="table-wrap"><table><thead><tr><th>Mức sống</th><th>Tiết kiệm</th><th>Phổ biến</th><th>Thoải mái / expat</th></tr></thead><tbody><tr><td>Nhà ở</td><td>1.800 RMB</td><td>2.700 RMB</td><td>&gt;3.500 RMB</td></tr><tr><td>Điện nước</td><td>300</td><td>450</td><td>600</td></tr><tr><td>Internet</td><td>100</td><td>100</td><td>100</td></tr><tr><td>Điện thoại</td><td>100</td><td>100</td><td>100</td></tr><tr><td>Ăn uống</td><td>1.300</td><td>1.800</td><td>3.000</td></tr><tr><td>Đi lại</td><td>100</td><td>300</td><td>300</td></tr><tr><td>Giải trí / chi tiêu thêm</td><td>0</td><td>1.000</td><td>2.000</td></tr><tr><td>Tổng / tháng</td><td><strong>3.700 RMB</strong></td><td><strong>6.450 RMB</strong></td><td><strong>9.600 RMB</strong></td></tr></tbody></table></div><p class="lead" style="margin-top:14px">Đây là mẫu ngân sách để lập kế hoạch, không phải mức bắt buộc. Tỷ giá RMB/VND thay đổi nên nên quy đổi sang VND tại thời điểm chuẩn bị hồ sơ và thanh toán.</p></section>
<section class="section"><h2>Chi phí dễ bị quên</h2><div class="grid"><article class="card"><h3>Tiền đặt cọc nhà</h3><p>Tùy nơi ở và hợp đồng; một số lựa chọn cần đặt cọc lớn hơn nếu trả tiền theo đợt.</p></article><article class="card"><h3>Phí dịch vụ học tập</h3><p>XJTLU gợi ý dự trù khoảng 2.000 RMB/năm hoặc 1.000 RMB/học kỳ cho các khoản như giáo trình, thẻ, in ấn và dịch vụ liên quan.</p></article><article class="card"><h3>Visa / giấy tờ</h3><p>Hướng dẫn ngân sách của XJTLU nêu ví dụ phí visa 400 RMB; các khoản thực tế cần kiểm tra tại thời điểm làm thủ tục.</p></article><article class="card"><h3>Vé máy bay & du lịch</h3><p>Vé về Việt Nam, đi Thượng Hải, tàu cao tốc và du lịch trong Trung Quốc có thể làm ngân sách tăng đáng kể.</p></article></div></section>
<section class="section"><h2>Tiết kiệm nhất ở đâu?</h2><div class="grid"><article class="card"><h3>Ăn trong campus</h3><p>Canteen và đồ ăn địa phương thường giúp giảm đáng kể chi phí so với ăn nhà hàng quốc tế thường xuyên.</p></article><article class="card"><h3>Ưu tiên metro / bus</h3><p>SIP có hệ thống metro và bus thuận tiện. Taxi/DiDi dùng thường xuyên sẽ làm ngân sách tăng nhanh.</p></article><article class="card"><h3>Chọn chỗ ở đúng nhu cầu</h3><p>Chỉ riêng tiền thuê có thể dao động từ khoảng 1.800 RMB/tháng trong kịch bản tiết kiệm đến trên 3.500 RMB cho studio tư nhân.</p></article><article class="card"><h3>Không hard-code VND quá sớm</h3><p>Học phí và tiền nhà thanh toán bằng RMB; khi lập kế hoạch dài hạn nên giữ ngân sách gốc bằng RMB rồi quy đổi VND theo tỷ giá gần thời điểm thanh toán.</p></article></div></section>
<section class="section"><h2>Ngân sách 1 năm nên tính như thế nào?</h2><div class="notice">Cách an toàn là tách riêng <strong>học phí + chỗ ở + sinh hoạt hàng tháng + bảo hiểm/visa + vé máy bay + quỹ dự phòng</strong>. Đừng lấy một con số “chi phí sinh hoạt Trung Quốc” chung cho mọi thành phố hoặc mọi kiểu sống.</div></section>
<section class="section"><h2>Xem tiếp</h2><div class="related"><a href="/xjtlu-hoc-phi-hoc-bong-2027.html">Học phí & học bổng 2027<span>Ghép học phí với ngân sách sinh hoạt</span></a><a href="/xjtlu-ky-tuc-xa-sip-taicang.html">Ký túc xá SIP & Taicang<span>So sánh loại phòng và giá</span></a><a href="/xjtlu-to-chau-thuong-hai-viet-nam.html">Tô Châu & Thượng Hải<span>Hiểu môi trường sống ngoài campus</span></a></div></section>'''
COST_FAQ=[('Sinh viên XJTLU cần bao nhiêu tiền sinh hoạt mỗi tháng?','Mẫu ngân sách hiện tại của XJTLU đưa ra khoảng 3.700 RMB cho lối sống tiết kiệm, 6.450 RMB cho mức phổ biến và 9.600 RMB cho lối sống thoải mái hơn.'),('Có nên đổi toàn bộ ngân sách sang VND ngay từ đầu không?','Không nên cố định tỷ giá quá sớm. Các khoản chính được tính bằng RMB, vì vậy nên giữ ngân sách gốc bằng RMB và quy đổi VND gần thời điểm thanh toán.'),('Học phí đã bao gồm ký túc xá và sinh hoạt chưa?','Không. Học phí, chỗ ở, sinh hoạt, bảo hiểm, visa, đi lại và chi tiêu cá nhân cần được tính riêng.')]

